module TopModule(
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg done
);
    reg [2:0] state;
    reg [7:0] buf [0:2];
    reg [2:0] byte;
    reg [2:0] bit;
    reg [7:0] parity;
    wire [7:0] dat;
    wire [7:0] par;
    reg [7:0] i;
    always @(posedge clk) begin
        if (reset) begin
            state <= 0;
            byte <= 0;
            bit <= 0;
            parity <= 0;
            done <= 0;
        end else begin
            case (state)
                0: begin
                    if (in[3] == 1) state <= 1;
                end
                1: begin
                    buf[0] <= in;
                    byte <= 1;
                    bit <= 0;
                    parity <= in ^ 8'h80;
                    state <= 2;
