                2: begin
                    buf[1] <= in;
                    byte <= 2;
                    bit <= 0;
                    parity <= parity ^ in;
                    state <= 3;
                end
                3: begin
                    buf[2] <= in;
                    byte <= 0;
                    bit <= 0;
                    if (parity ^ in == 0) done <= 1;
                    state <= 1;
