// Finite State Machine (FSM) to search for PS/2 message boundaries.
// Detects messages by waiting for the first byte of a message (byte 1) to
// appear in the stream. Once this is detected, it assumes that the first
// byte is indeed byte 1 and starts waiting for byte 2 and 3 of the message
// to follow. The FSM signals done in the cycle immediately after byte 3 has
// been received.
module TopModule(
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg done
);
    reg [1:0] state;
    reg [7:0] bytes [0:2];
    integer i;
    reg [1:0] byte_count;

    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            byte_count <= 2'b00;
            done <= 1'b0;
        end else begin
            case (state)
                2'b00: begin // Wait for first byte of a message.
                    if (in[3] == 1'b1) begin
                        state <= 2'b01;
                        bytes[0] <= in;
                        byte_count <= 2'b01;
                    end
                end
                2'b01: begin // Wait for second byte of a message.
                    bytes[1] <= in;
                    byte_count <= 2'b10;
                    if (in[3] == 1'b0) state <= 2'b00;
                end
                2'b10: begin // Wait for third byte of a message.
                    bytes[2] <= in;
                    byte_count <= 2'b11;
                    state <= 2'b00;
                    done <= 1'b1;
                end
            endcase
        end
    end

    // Assert reset for one cycle to start the FSM.
    // The FSM will wait for the first byte of the first message to appear.
    // Once this is detected, it assumes that the first byte is indeed
    // byte 1 and starts waiting for byte 2 and 3 of the message to follow.
    // The FSM signals done in the cycle immediately after byte 3 has been
    // received.
    reg reset_asserted = 1'b1;
    always @(posedge clk) reset_asserted <= 1'b0;
    TopModule uut(
        .clk(clk),
        .reset(reset_asserted),
        .in(bytes[byte_count]),
        .done(done)
    );
endmodule

